const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C=Core,N=globalThis.Native;
let initial=N?JSON.parse(N.init()):{},S={...C.blank(),...(initial.state||{})},B=initial.billing||{active:false,plans:[],message:''},tab='Morning',screen='',draft=null,editingStep=0,returnScreen='',session=S.session,started=false,finished=false,progress=0,reps=0,muted=false,sensor='',movingAt=0,tickAt=0,mood=null,mathQ=null,memory=null,feedback='',scanSave=false,selectedPlan='com.oanarinaldi.wakemeup.plus.yearly',nap=20;
const paths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4.2 4.2l1.5 1.5m12.6 12.6 1.5 1.5M4.2 19.8l1.5-1.5M18.3 5.7l1.5-1.5"/>',rise:'<path d="M2 18h20M4 22h16M6 15a6 6 0 0 1 12 0M12 2v3M3 8l2 2m14 0 2-2"/>',dance:'<circle cx="14" cy="3" r="2"/><path d="m11 7 5 4 4-2M11 7 8 3 7 0m4 7-2 7-5 6m5-6 6 2 2 6m-6-15 6-1"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="3"/><path d="M7 2v5m10-5v5M3 11h18m-14 4h1m4 0h1m4 0h1m-10 4h1m4 0h1"/>',settings:'<path d="M3 5h10m5 0h3M3 12h3m5 0h10M3 19h11m5 0h2"/><circle cx="15" cy="5" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="19" r="2"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',close:'<path d="m4 4 16 16M4 20 20 4"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v7l4 2"/>',heart:'<path d="M12 21 3 12C-3 4 6-2 12 5 18-2 27 4 21 12Z"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5ZM16 7c3 3 3 7 0 10m4-14c5 5 5 13 0 18"/>',mute:'<path d="m11 4-6 5H2v6h3l6 5ZM17 9l6 6m-6 0 6-6"/>',pause:'<path d="M8 4v16M16 4v16"/>',play:'<path d="m7 3 14 9L7 21Z"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15Z"/>',route:'<circle cx="5" cy="4" r="2"/><circle cx="19" cy="20" r="2"/><path d="M5 6v6c0 4 14-4 14 2v4"/>',scan:'<path d="M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5M8 8h3v3H8zm6 0h2v3h-2zm-6 6h3v2H8zm6 0h2v2h-2z"/>',cup:'<path d="M3 8h14v7a6 6 0 0 1-12 0V8m12 1h2a3 3 0 0 1 0 6h-2M2 22h18M7 2v2m5-2v2"/>',wind:'<path d="M2 8h14a3 3 0 1 0-3-3M2 12h18a3 3 0 1 1-3 3M2 16h8a3 3 0 1 1-3 3"/>',math:'<path d="M3 6h8M7 2v8m6 8h8M20 3 4 21"/>',memory:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',words:'<path d="M3 4h14M10 4v16M6 20h8m5-17h4m-2 0v18m-2 0h4"/>',pushups:'<circle cx="4" cy="9" r="2"/><path d="m6 10 5 2 9 3 2 5m-11-8-3 8H3"/>',squats:'<circle cx="12" cy="3" r="2"/><path d="m12 6-3 6 7 3-3 6m-4-9H3m7 3-5 6h5m2-15 7 4"/>',stretch:'<circle cx="12" cy="3" r="2"/><path d="M12 6v8m0-7L4 4m8 3 8-3m-8 10-5 8m5-8 5 8"/>',dot:'<circle cx="12" cy="12" r="8" stroke-dasharray="1 4"/>'};
const icon=(id='sun')=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[id]||paths.sun}</svg>`;
const micon=id=>({pushups:'pushups',squats:'squats',dance:'dance',march:'dance',stretch:'stretch',breathe:'wind',sunTaps:'sun',math:'math',memory:'memory',words:'words',scanCode:'scan',daylight:'sun',water:'cup'}[id]||'sun');
const mission=id=>MISSIONS.find(m=>m.id===id)||MISSIONS[2];
const btn=(text,action,symbol='arrow',cls='primary')=>`<button class="${cls}" data-action="${esc(action)}" aria-label="${esc(text||({new:'Add alarm',exit:'Exit ritual',mute:'Mute or unmute music'}[action])||action)}">${esc(text)}${symbol?icon(symbol):''}</button>`;
const heading=(eyebrow,title,sub='')=>`<header class="heading"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</header>`;
const card=(body,cls='')=>`<section class="card ${cls}">${body}</section>`;
const fmt=(n,opts={hour:'numeric',minute:'2-digit'})=>new Date(n).toLocaleString('en-US',opts);
const dateTime=n=>fmt(n,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const timeOf=a=>{let d=new Date();d.setHours(a.hour,a.minute,0,0);return fmt(d)};
const routeText=a=>a.route.map(s=>mission(s.mission).title).join(' → ');
const repeatText=a=>a.isNap?'Quick nap':a.scheduleMode==='dated'?fmt(a.datedAt,{month:'short',day:'numeric'}):a.scheduleMode==='rotation'?`${a.workDays} on · ${a.restDays} off`:!a.weekdays.length?'Once':a.weekdays.length===7?'Every day':JSON.stringify([...a.weekdays].sort())==='[1,2,3,4,5]'?'Weekdays':[...a.weekdays].sort().map(x=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][x]).join(' · ');
const toggle=(name,checked,scope='pref')=>`<input class="switch" type="checkbox" aria-label="${esc(name)}" data-${scope}="${esc(name)}" ${checked?'checked':''}>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function save(){S.session=session;let error=N?.save(JSON.stringify(S));if(error){toast(error);return false}return true}
function page(html,cls=''){ $('#app').innerHTML=`<div class="page ${cls}">${html}</div>`;renderTabs() }
function renderTabs(){let hidden=!S.welcomed||session||screen==='bedside'||screen==='check';$('#tabs').style.display=hidden?'none':'flex';$('#tabs').innerHTML=['Morning','Move','Sunrises','Settings'].map((t,i)=>`<button class="${tab===t?'active':''}" data-action="tab:${t}" aria-current="${tab===t?'page':'false'}">${icon(['sun','dance','calendar','settings'][i])}<span>${t}</span></button>`).join('')}
function render(){if(!S.welcomed){welcome();return}if(session){renderRitual();return}if(screen==='check'){renderCheck();return}if(screen==='bedside'){bedside();return}if(tab==='Morning')home();else if(tab==='Move')routines();else if(tab==='Sunrises')journal();else settings();if(screen)renderScreen();else $('#modal').innerHTML=''}
function welcome(){page(`<div class="eyebrow">WAKE ME UP</div><img class="landscape" src="art/sunrise.png" alt=""><h1>Bring your<br>sunshine back.</h1><p class="center">An alarm. A little movement.<br>A morning that starts with you.</p><div class="stack">${[['dance','Push up, dance, or stretch gently'],['lock','Optional camera counting stays on device'],['heart','No account. No ads. Your own pace.']].map(([i,t])=>`<div class="row">${icon(i)}${t}</div>`).join('')}</div>${btn('Make room for morning','welcome','sun')}<p class="small center">Android keeps its own alarm controls. Open Wake Me Up to complete your movement ritual.</p>`,'welcome')}
function home(){let next=S.alarms.filter(a=>C.nextFire(a)).sort((a,b)=>C.nextFire(a)-C.nextFire(b))[0],fire=next&&C.nextFire(next);let hero=card(`<div class="heroart"><img src="art/sunrise.png" alt=""><div class="badge row">${icon('rise')}YOUR NEXT SUNRISE</div></div><div class="herocopy"><h2 class="${next?'time':''}">${next?esc(fmt(fire)):'A fresh start.'}</h2>${next?`<p>${esc(next.label)} · ${esc(repeatText(next))}</p><strong class="small row">${icon('route')}${esc(routeText(next))}</strong><p class="small">${fmt(fire,{weekday:'long',month:'short',day:'numeric'})}</p><p class="small">Wind down around ${fmt(fire-S.sleepGoalHours*3600000)} for your ${S.sleepGoalHours}-hour rest goal.</p>`:'<p>Set an alarm tonight. Meet a brighter you tomorrow.</p>'}${btn(next?'Edit my morning':'Set my first alarm',next?'edit:'+next.id:'new','plus')}</div>`,'hero');let alarms=`<div class="stack"><div class="row between"><h3>Your alarms</h3>${btn('','new','plus','circlebutton')}</div>${!S.alarms.length?card('<strong>Start with something small</strong><p>Five push-ups. Thirty seconds of dancing. A gentle stretch. Choose what feels like you.</p>'):S.alarms.map(a=>card(`<div class="row"><button class="alarmcopy grow" data-action="edit:${a.id}"><div class="alarmtime rounded" style="color:${a.enabled?'var(--ink)':'var(--muted)'}">${esc(timeOf(a))}</div><span class="small">${esc(a.label)} · ${esc(repeatText(a))}</span><strong class="small row">${icon(micon(a.route[0].mission))}${esc(routeText(a))}</strong></button><input type="checkbox" class="switch" data-alarm="${a.id}" aria-label="Enable ${esc(a.label)}" ${a.enabled?'checked':''}></div>${a.enabled&&C.nextFire(a)?`<p class="small">Next: ${dateTime(C.nextFire(a))}</p>${btn('Skip next','skip:'+a.id,'','textbutton')}`:''}`)).join('')}<p class="small">${icon('check')} System alarms work when the app is closed.</p><p class="small">Open the movement action to start your ritual. Android keeps its own dismissal controls. Force-stopping the app or powering off the device prevents alarms.</p></div>`;page(`${heading(fmt(Date.now(),{weekday:'long',month:'long',day:'numeric'}),'Hello, sunshine.','A small move. A brighter morning.')}<div class="heroandalarms">${hero}${alarms}</div><button class="card row between green toolslink" data-action="screen:tools">${icon('moon')}<span>Morning tools</span><span class="small grow">Naps · days off · bedside</span>${icon('arrow')}</button>${S.wakeChecks.map(c=>card(`<div class="row between"><span class="small">Wake-up check · ${fmt(c.date)}</span>${btn('Cancel','cancelcheck:'+c.id,'','textbutton')}</div>`)).join('')}<h3>Find your morning rhythm</h3><div class="grid">${MISSIONS.map(m=>`<button class="card tile ${m.tint}" data-action="practice:${m.id}"><div class="row between">${icon(micon(m.id))}${icon('up')}</div><div><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p></div></button>`).join('')}</div>${btn('Your morning, with more possibilities. Meet Wake Me Up Plus','screen:plus','up','card row between')}`,'home')}
function routines(){page(`${heading('Movement menu','Start small. Feel good.','Find your rhythm before the alarm rings. Practice never changes your sunrise streak.')}${card(`<h2>Try a whole morning route</h2><p>Focus, move, then prepare something for your day. Practice never adds journal credit.</p>${btn('Sun taps → stretch → light','practiceRoute','route')}${S.presets.map(p=>btn('Try '+p.name,'presetPractice:'+p.id,'','textbutton')).join('')}`,'green')}${MISSIONS.map(m=>card(`<div class="row between">${icon(micon(m.id))}<span class="chip small">${m.target} ${m.unit}</span></div><h2>${esc(m.title)}</h2><strong class="small orange">${esc(m.countingHint)}</strong><p>${esc(m.instructions)}</p>${btn('Try '+m.title.toLowerCase(),'practice:'+m.id,'play')}`,m.tint)).join('')}${card(`<h2>A longer little ritual</h2><p>Plus lets you choose up to 30 reps or sun taps, or 3 minutes of a timed challenge. Keep your goal comfortable and achievable.</p>${btn(B.active?'Practice a 60-second dance':'Explore Plus',B.active?'longDance':'screen:plus','up')}`)}`)}
function journal(){let unique=new Set(S.sunrises.map(x=>C.localDate(x.date))),recent=S.sunrises.filter(x=>x.date>Date.now()-7*86400000),durations=recent.map(x=>x.durationSeconds).filter(Number.isFinite);page(`${heading('Your sunrise journal','Look at you, showing up.','A little collection of mornings you made your own.')}<div class="statrow">${!S.hideStreak?card(`${icon('sun')}<strong>${C.streak(S.sunrises)}</strong><p>day streak</p>`,'metric'):''}${card(`${icon('rise')}<strong>${unique.size}</strong><p>bright mornings</p>`,'metric')}</div>${card(`<h3>Your last seven days</h3><div class="row between"><div><h2>${new Set(recent.map(x=>C.localDate(x.date))).size}</h2><p class="small">bright mornings</p></div><div><h2>${recent.filter(x=>x.wakeCheckConfirmedAt).length}</h2><p class="small">wake-up checks confirmed</p></div></div>${durations.length?`<p class="small">Average route time: ${Math.round(durations.reduce((a,b)=>a+b,0)/durations.length)} seconds, including pauses.</p>`:''}<p class="small">Only completed alarm routes count here. Practice stays separate. Your history is a record of returns, not a score you have to protect.</p>`,'green')}${btn('Export my sunrise journal','export','','textbutton')}${card(`<h3>The last 28 days</h3><div class="calendar">${Array.from({length:28},(_,i)=>{let d=new Date();d.setDate(d.getDate()-27+i);let done=unique.has(C.localDate(d));return`<div class="${i===27?'today':''}" aria-label="${fmt(d,{dateStyle:'full'})}, ${done?'sunrise completed':'no completed ritual'}" style="color:${done?'var(--orange)':'var(--muted)'}">${icon(done?'sun':'dot')}${d.getDate()}</div>`}).join('')}</div><p class="small">A streak counts consecutive days with a completed alarm ritual. Multiple alarms on one day count as one bright morning.</p>`)}<h3>Morning moments</h3>${!S.sunrises.length?card(`${icon('rise')}<h2>Your first sunrise is waiting.</h2><p>Complete a movement after an alarm, then save your sunrise. No pressure to be perfect.</p>`,'peach center'):S.sunrises.slice().sort((a,b)=>b.date-a.date).map(r=>card(`<div class="row">${icon(micon(r.steps[0].mission))}<div class="grow"><strong>${fmt(r.date,{month:'long',day:'numeric'})}</strong><p class="small">${esc(r.steps.map(s=>`${mission(s.mission).title} · ${s.amount} ${mission(s.mission).unit}`).join(' → '))}</p><p class="small">${esc(r.steps.map(s=>s.mode).join(' · '))}</p></div>${r.wakeCheckConfirmedAt?icon('check'):''}<span class="small orange">${esc(r.mood||'')}</span></div>`)).join('')}`)}
const field=(text,body)=>`<div class="field"><label>${esc(text)}</label>${body}</div>`, hint=t=>`<p class="hint">${esc(t)}</p>`,section=(title,body,foot='')=>`<section><div class="sectiontitle">${esc(title)}</div><div class="formgroup">${body}</div>${foot?hint(foot):''}</section>`;
const linkField=(text,action)=>`<div class="field">${btn(text,action,'','textbutton')}</div>`;
const pref=(label,key)=>field(label,toggle(key,S[key]));
function settings(){let ready=N?JSON.parse(N.readiness()):{exact:false,notifications:false};page(`${heading('Make it yours','Morning settings.')}${section('Alarms and movement',field('System alarm access',`<span class="small">${ready.exact&&ready.notifications?'Allowed':'Not enabled'}</span>`)+linkField('Open app permissions','permissions')+pref('Play music during rituals','soundEnabled'),'Music follows the device volume. System alarm sounds are separate. Test an alarm on this device before relying on it.')}${section('Comfort and rest',`<div class="field col"><label for="volume">Ritual music volume · ${Math.round(S.ritualVolume*100)}%</label><input id="volume" type="range" min="0.05" max="1" step="0.05" value="${S.ritualVolume}" data-pref="ritualVolume"></div>`+pref('Hide the consecutive-day streak','hideStreak')+field(`${S.sleepGoalHours} hours planned for rest`,`<input type="number" min="4" max="12" step="0.5" value="${S.sleepGoalHours}" data-pref="sleepGoalHours" aria-label="Hours planned for rest">`)+pref('Bedtime reminder','bedtimeEnabled')+field('Wind-down time',`<input type="time" data-pref="bedtime" value="${String(S.bedtimeHour).padStart(2,'0')}:${String(S.bedtimeMinute).padStart(2,'0')}">`)+linkField('Alarm readiness and bedside tools','screen:tools')+linkField('Saved destination codes','screen:destinations')+linkField('Saved routes and sounds','screen:library'),'This helps you plan a wind-down time. It does not track sleep or prescribe how long you should sleep. Android controls system alarm volume separately.')}${section('Wake Me Up Plus',linkField(B.active?'Your Plus plan':'Explore Plus','screen:plus')+linkField('Restore purchases','restore')+linkField('Manage subscriptions','manage'))}${section('Your privacy',`<div class="field col"><strong>No account or advertising</strong><p>Alarms, moods, and journal entries stay on this device. Optional camera images and motion readings are processed locally and never recorded or uploaded. Google Play handles purchases. App backup is disabled on Android.</p></div>`+linkField('Privacy policy','link:privacy')+linkField('Export sunrise journal','export')+linkField('Clear sunrise journal','clearJournal'),'Export is a CSV file you choose where to share. Nothing is uploaded automatically.')}${section('A little help',linkField('Support and alarm guide','link:support')+linkField('Contact Oana','contact')+linkField('Terms of use','link:terms')+(B.reviewAvailable?linkField(B.review?'End Play review access':'Play review access','reviewAccess'):''),'Move within your comfort. Camera and motion counts are estimates. This app is a morning habit tool, not a medical or fitness assessment.')}<h3>Made for brighter mornings.</h3><p class="small">Wake Me Up 1.0 · build 2 · by Oana Rinaldi</p>`)}
function openScreen(name){screen=name;render();$('#modal').scrollTop=0}
function modal(title,body,saveAction=''){ $('#modal').innerHTML=`<header class="toolbar">${btn('Back','back','','textbutton')}<strong>${esc(title)}</strong>${saveAction?btn('Save',saveAction,'','textbutton'):btn('Done','close','','textbutton')}</header><div class="form">${body}</div>` }
function renderScreen(){if(screen==='editor')editor();else if(screen==='step')stepEditor();else if(screen==='tools')tools();else if(screen==='readiness')readiness();else if(screen==='destinations')destinations();else if(screen==='library')library();else if(screen==='plus')plus()}
const input=(key,value,type='text',extra='')=>`<input type="${type}" data-draft="${key}" value="${esc(value)}" ${extra}>`;
const select=(key,value,choices,scope='draft')=>`<select data-${scope}="${key}" aria-label="${esc(key)}">${choices.map(([id,t])=>`<option value="${id}" ${String(value)===String(id)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
function editor(){let a=draft,dates=C.occurrences({...a,enabled:true},Date.now(),7),time=`${String(a.hour).padStart(2,'0')}:${String(a.minute).padStart(2,'0')}`;
 modal(S.alarms.some(x=>x.id===a.id)?'Your morning':'New morning',section('',`<div class="field col">${input('time',time,'time','aria-label="Wake-up time"')}</div><div class="field">${input('label',a.label,'text','maxlength="48" placeholder="Name your morning" aria-label="Name your morning"')}</div>`)+section('Schedule',field('Repeats',select('scheduleMode',a.scheduleMode,[['weekly','Weekdays'],['dated','A specific date'],['rotation','Work / rest cycle']]))+(a.scheduleMode==='weekly'?`<div class="field"><div class="days">${['S','M','T','W','T','F','S'].map((d,i)=>`<button class="${a.weekdays.includes(i)?'on':''}" data-action="weekday:${i}" aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}" aria-pressed="${a.weekdays.includes(i)}">${d}</button>`).join('')}</div></div>`:a.scheduleMode==='dated'?field('Date and time',input('datedAt',localInput(a.datedAt),'datetime-local')):field('First work day',input('cycleStart',C.localDate(a.cycleStart),'date'))+field('Work days',input('workDays',a.workDays,'number','min="1" max="30"'))+field('Rest days',input('restDays',a.restDays,'number','min="1" max="30"'))),repeatText(a))+section('Your morning route',a.route.map((s,i)=>`<div class="field"><button class="grow" data-action="step:${i}"><strong>Step ${i+1} · ${esc(mission(s.mission).title)}</strong><p class="small">${s.target} ${mission(s.mission).unit}</p></button>${i>0?btn('↑','earlier:'+i,'','textbutton'):''}${i<a.route.length-1?btn('↓','later:'+i,'','textbutton'):''}${a.route.length>1?btn('×','removeStep:'+i,'','textbutton'):''}</div>`).join('')+(a.route.length<5?linkField('Add a step','addStep'):'')+field('Ready-made route',select('preset','',[['','Choose a ready-made route'],['gentle','Gentle start · breathe, stretch, light'],['focus','Focus and feet · maths, march, destination'],['joy','Tiny joy · sun taps, dance, drink'],...S.presets.map(p=>[p.id,p.name])]))+linkField('Save as a reusable route','savePreset'),'Up to five short steps. Every standard challenge and multi-step route is free.')+section('Snooze and stay-awake check',field('System snooze',select('snoozeMinutes',a.snoozeMinutes,[[0,'Off · start my route'],...[3,5,10,15].map(x=>[x,x+' minutes'])]))+field("Check I'm still awake",select('wakeCheckMinutes',a.wakeCheckMinutes,[[0,'Off'],...[3,5,10,15].map(x=>[x,x+' minutes after completing my route'])])),'An optional second system alarm follows a completed route. Confirm three sun taps, or cancel it anytime. Android retains its own dismissal controls.')+section('Sound',field('Alarm ringtone',select('tone',a.tone,toneOptions()))+field('Gentle sound ramp',toggle('gentleSound',a.gentleSound,'draft'))+linkField('Preview selected sound','preview')+linkField('Stop preview','stopPreview')+linkField('Import my own audio','importAudio'),'Bundled tones can rise gently over 15 seconds. Android controls alarm volume. Import a playable, non-DRM audio file you have permission to use. Its first 25 seconds stay on this device.')+(a.scheduleMode!=='dated'?section('Days off and exceptions',field('Change just the next wake-up time',toggle('override',!!a.nextOverride,'draft'))+(a.nextOverride?field('Next wake-up only',input('nextOverride',localInput(a.nextOverride),'datetime-local')):'')+field('Skip this date','<input type="date" id="skipDate" aria-label="Skip this date">')+linkField('Add day off','addDayOff')+a.skippedDates.map(d=>field(d,btn('Remove','removeDay:'+d,'','textbutton'))).join('')+(a.pausedUntil?field('Paused until '+dateTime(a.pausedUntil),btn('End pause','endPause','','textbutton')):'')):'')+section('Next wake-ups',dates.length?dates.map(d=>field(fmt(d,{weekday:'short',month:'short',day:'numeric'}),`<strong>${fmt(d)}</strong>`)).join(''):'<div class="field">Choose a future date.</div>','Android schedules the next occurrence and renews it when it rings. Open the app after force-stopping it to restore alarms.')+section('',field('Enable this alarm',toggle('enabled',a.enabled,'draft')))+(S.alarms.some(x=>x.id===a.id)?section('',linkField('Delete alarm','deleteAlarm')):''),'saveAlarm')}
function localInput(ms){let d=new Date(ms);return C.localDate(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
const toneOptions=()=>[['FirstLight','First Light · joyful marimba'],['SoftStart','Soft Start · gentle piano'],['RiseAndShine','Rise & Shine · upbeat funk'],['BrightMarimba','Bright Marimba · lively refrain'],['QuietKeys','Quiet Keys · soft piano'],['MorningGroove','Morning Groove · funk refrain'],['Surprise','Different sound each morning'],...S.importedTones.map(t=>[t.id,t.name])];
function stepEditor(){let s=draft.route[editingStep],m=mission(s.mission),range=m.unit==='seconds'?[10,180,10]:m.target===1?[1,1,1]:[1,m.id==='math'||m.id==='memory'?10:30,1];modal(m.title,section('',field('Challenge',select('mission',s.mission,MISSIONS.map(m=>[m.id,m.title]),'step'))+`<div class="field"><p>${esc(m.instructions)}</p></div>`)+section('Your goal',B.active&&range[1]>1?field(m.unit,`<input type="number" min="${range[0]}" max="${range[1]}" step="${range[2]}" value="${s.target}" data-step="target" aria-label="Target ${m.unit}">`):`<div class="field">${s.target} ${m.unit}</div>`)+(m.id==='math'||m.id==='memory'?field('Difficulty',select('difficulty',s.difficulty,[[1,'Easy'],[2,'Medium'],[3,'Stretch my focus']],'step')):'')+(m.id==='words'?`<div class="field col"><label>My morning intention</label><textarea data-step="intention" maxlength="160">${esc(s.intention)}</textarea></div>`:'')+(m.id==='scanCode'?field('Destination',select('destinationID',s.destinationID||'',[['','Guided check-in'],...S.destinations.map(d=>[d.id,d.name])],'step'))+linkField('Save a destination code','stepDestinations'):'')+(!B.active?hint('Plus adds adjustable goals. Every standard challenge stays free.') :''))}
function tools(){modal('Morning tools',heading('Make waking up easier','Little morning tools.','Short rests, a calmer bedside view, and clear checks before you rely on an alarm.')+section('A quick nap',field('Rest for',select('nap',nap,[10,15,20,30,45,60,90].map(x=>[x,x+' minutes']),'tool'))+linkField(`Set a ${nap}-minute nap`,'setNap'),'One quick nap in addition to your saved alarms. Setting another nap replaces the previous nap.')+section('Time off',field('Pause alarms until',`<input type="datetime-local" id="pauseUntil" value="${localInput(Date.now()+86400000)}">`)+linkField('Pause my enabled alarms','pauseAll'),'Your next wake-ups appear on Morning. You can end the pause in each alarm editor.')+section('Before bed',linkField('Open bedside clock','bedside')+linkField('Alarm readiness check','screen:readiness')+linkField('Saved destination codes','screen:destinations'),'The bedside view is optional. System alarms do not need it open to ring.'))}
function readiness(){let r=N?JSON.parse(N.readiness()):{};modal('Alarm readiness',section('On this device',`<div class="field">${r.exact?'✓ Exact alarm access allowed':'Alarm access is not allowed'}</div><div class="field">${r.notifications?'✓ Notifications allowed':'Notifications are not allowed'}</div><div class="field">${r.fullScreen?'✓ Lock-screen alarm display allowed':'Allow full-screen alarms for locked-screen display'}</div>`+linkField('Open app permissions','permissions')+(!r.fullScreen?linkField('Allow full-screen alarm display','fullScreenPermission'):''),'Keep the device powered on. Android controls system alarm volume and sound routing. Force-stopping the app prevents its alarms until you open it again.')+section('Try a real alarm',linkField('Schedule a one-minute sound test','testAlarm')+field('I heard the alarm on this device','<input class="switch" type="checkbox" aria-label="I heard the alarm on this device">'),'This uses the quick-nap slot. Lock the device and confirm that the system alarm rings. Try Do Not Disturb too. This is your own checklist, not an automatic hardware test result.')+section('Optional counting','<div class="field"><p>Try camera counting from a secure side view. For dance or marching, try gentle movement with the phone securely held. Switch to guided counting if estimates are unreliable.</p></div>')+section('Calendar plans',linkField('Refresh calendar plans','refresh'),'Weekly repeats, rotations, pauses, days off and sound changes renew with each alarm. Boot and timezone changes reschedule your next wake-ups.'))}
function destinations(){modal('Destinations',section('',`<div class="field"><p>Choose a code on a comfortable destination: a cereal box, toothpaste, or a QR label. Only a one-way code fingerprint is saved.</p></div><div class="field"><input id="destinationName" placeholder="Destination name" value="Kitchen" maxlength="48"></div>`+linkField('Scan a barcode or QR code','scanDestination'))+section('Your destinations',S.destinations.length?S.destinations.map(d=>field(d.name,btn('Remove','removeDestination:'+d.id,'','textbutton'))).join(''):'<div class="field"><p>No destination codes yet. Guided check-in is always available.</p></div>','Removing a destination returns routes using it to guided check-in.'))}
function library(){modal('Saved routes and sounds',section('Reusable morning routes',S.presets.length?S.presets.map(p=>field(p.name,btn('Remove','removePreset:'+p.id,'','textbutton'))).join(''):'<div class="field">Save a route from the alarm editor.</div>','Removing a preset keeps routes already copied into alarms.')+section('Imported sounds',S.importedTones.length?S.importedTones.map(t=>field(t.name,btn('Remove','removeTone:'+t.id,'','textbutton'))).join(''):'<div class="field">Import audio in an alarm’s sound settings.</div>','Change alarms using a sound before removing it. Audio is stored only on this device.'))}
function plus(){modal('Wake Me Up Plus',`<div class="eyebrow">WAKE ME UP PLUS</div><div class="row"><h1 class="grow">More room<br>for your mornings.</h1><img src="art/sun.png" style="width:100px;height:100px;border-radius:50%" alt=""></div><p>Make a ritual that feels like you. All the essentials stay free.</p>${card(`<h3>Up to 20 alarms</h3><p>Weekdays, weekends, and every rhythm in between.</p><h3>Your own movement goals</h3><p>1–30 reps or sun taps, or 10–180 seconds of a timed challenge.</p><h3>Longer practice sessions</h3><p>Build confidence with a 60-second dance ritual.</p>`,'peach')}${B.review?'<strong>Plus is available in Play review mode.</strong>':B.active?`<strong>Plus is active. Welcome, sunshine.</strong>${btn('Manage subscription','manage','up')}`:B.plans.length?B.plans.map(p=>`<button class="card plan ${p.id===selectedPlan?'selected':''}" data-action="plan:${p.id}"><strong>${esc(p.title)}</strong><p>${esc(p.price)} / ${p.period}</p>${p.period==='year'?'<span class="small">A YEAR OF SUNRISES</span>':''}</button>`).join('')+btn(B.busy?'Please wait…':`Subscribe · ${B.plans.find(x=>x.id===selectedPlan)?.price||B.plans[0].price} / ${B.plans.find(x=>x.id===selectedPlan)?.period||B.plans[0].period}`,'subscribe','sun'):`<p>Google Play’s subscription prices are unavailable right now. Try again, or keep enjoying the free app.</p>${btn('Reload plans','restore','','textbutton')}`}<p class="small">Auto-renewing subscription. Payment is charged to your Google Play account. Renews at the selected price unless canceled before renewal. Manage or cancel in Google Play → Payments &amp; subscriptions → Subscriptions.</p>${btn('Restore purchases','restore','','textbutton')}${B.message?`<p>${esc(B.message)}</p>`:''}<div class="row between">${btn('Privacy','link:privacy','','textbutton')}${btn('Terms','link:terms','','textbutton')}</div><p class="small">Free: two alarms, all thirteen challenges, multi-step routes, flexible schedules, wake-up checks, sound import, optional camera and motion counting, journal, and unlimited standard practice. No login or ads.</p>`)}
function startSession(a,practice){pauseRitual();screen='';$('#modal').innerHTML='';session={id:C.uid(),alarm:structuredClone(a),practice,steps:structuredClone(a.route),stepIndex:0,completedSteps:[],startedAt:Date.now(),amount:0,mode:'guided',finished:false};resetStep();save();render();window.scrollTo(0,0)}
function resetStep(){started=false;finished=!!session?.finished;progress=session?.amount||0;reps=Math.floor(progress);sensor='';mathQ=null;memory=null;feedback='';mood=null;tickAt=0}
function current(){return session.steps[session.stepIndex]}
function renderRitual(){let s=current(),m=mission(s.mission),amount=m.unit==='seconds'?Math.floor(progress):reps;finished=session.finished||false;let completion=finished?`<img class="mascot" src="art/sun.png" alt=""><h1 class="completiontitle">You brought<br>the sunshine.</h1><p>${session.stepIndex<session.steps.length-1?'A small step, done. Your next little action is ready.':session.practice?'A little practice is a lovely start. Your streak grows when you complete an alarm ritual.':'One small promise to yourself, kept.<br>How does your morning feel?'}</p>${!session.practice&&session.stepIndex===session.steps.length-1?`<div class="row">${['Sleepy','Okay','Bright'].map(x=>`<button class="chip ${mood===x?'selected':''}" data-action="mood:${x}">${x}</button>`).join('')}</div>`:''}${btn(session.stepIndex<session.steps.length-1?'Continue my morning route':session.practice?'Back to my morning':'Save my sunrise','completeStep',session.stepIndex<session.steps.length-1?'arrow':'sun')}`:'';
 let controls='';if(!finished&&started){if(m.id==='sunTaps'){let spot=[0,3,1,2][reps%4];controls=`<div class="grid">${[0,1,2,3].map(i=>`<button class="${i===spot?'lit':''}" data-action="sunTap:${i}" ${i===spot?'':'disabled'} aria-label="${i===spot?'Tap the sun':'Empty spot'}">${icon(i===spot?'sun':'dot')}</button>`).join('')}</div>`}else if(m.id==='math'){if(!mathQ)newQuestion();controls=`<h1 id="mathPrompt">${mathQ.a} ${mathQ.op} ${mathQ.b}</h1><input class="answer" id="answer" inputmode="numeric" placeholder="Your answer" aria-label="Your answer">${btn('Check my answer','answerMath','check')}`}else if(m.id==='memory'){if(!memory)newMemory();controls=`<strong class="center">${memory.show?'Remember the numbered trail.':'Tap the same spots, in order.'}</strong><div class="grid">${[0,1,2,3].map(i=>`<button data-action="memoryTap:${i}" ${memory.show?'disabled':''} aria-label="Spot ${i+1}" class="lit">${icon(memory.show&&memory.seq.includes(i)?'sun':'dot')}<span>${memory.show?(memory.seq.indexOf(i)>=0?memory.seq.indexOf(i)+1:''):i+1}</span></button>`).join('')}</div>${btn(memory.show?"I'm ready to repeat it":'Replay the trail','memoryToggle','','textbutton')}`}else if(m.id==='words'){controls=`<h2 class="center">${esc(s.intention)}</h2><input id="answer" class="answer" placeholder="Type your intention" aria-label="Type your intention">${btn('Keep this little promise','answerWords','check')}`}else if(m.id==='scanCode'){let d=S.destinations.find(d=>d.id===s.destinationID);controls=`<p>${d?'Reach '+esc(d.name):'Go to your chosen destination.'}</p>${d?btn('Scan my saved code','scanRitual','scan'):''}${btn("I'm at my destination · honest check-in",'destinationManual','check')}`}else if(m.id==='daylight'||m.id==='water'){controls=btn(m.id==='daylight'?"I've let in some light":"I've prepared my drink",'selfAction','check')}else if(m.unit==='reps'){controls=btn(m.id==='pushups'?'One push-up done':'One squat done','rep','plus')}else{controls=btn('Pause for a breath','pause','pause')}if(sensor)controls+=btn('Switch to guided mode','guided','','textbutton');}
 page(`<div class="row"><div class="eyebrow grow">${session.practice?'A LITTLE PRACTICE':'YOUR MORNING RITUAL'}</div>${btn('', 'mute',muted?'mute':'sound','textbutton')}${btn('','exit','close','textbutton')}</div>${session.steps.length>1?`<div class="row routeicons">${session.steps.map((s,i)=>icon(i<session.stepIndex?'check':micon(s.mission))).join('')}</div><div class="small center">STEP ${session.stepIndex+1} OF ${session.steps.length} · ${esc(m.title.toUpperCase())}</div>`:''}${finished?completion:`<h1>${started?'Here comes your sun.':esc(m.title)}</h1><div class="sunrise-stage" style="--stage-color:var(--${m.tint})"><img class="mascot" id="risingSun" src="art/sun.png" alt="" style="transform:translateY(${(1-Math.min(1,amount/s.target))*28}px)"></div>${started?`<div><div class="progressnumber" id="progressNumber">${amount} / ${s.target}</div><div class="unit">${m.unit.toUpperCase()}</div><div class="progress"><span id="progressBar" style="width:${Math.min(100,amount/s.target*100)}%"></span></div><p id="cue">${esc(m.unit==='seconds'?timerCue(m.id,amount):m.countingHint)}</p></div>${controls}`:`<p>${esc(m.instructions)}</p>${btn(amount?'Continue my morning':'Start in guided mode','start','play')}${m.id==='pushups'?btn('Use camera counting','cameraPose','','textbutton'):m.id==='dance'||m.id==='march'?btn('Use motion counting','motion','','textbutton'):''}`}<p class="small center" id="feedback">${esc(feedback)}</p><p class="small center">Move only if it feels comfortable. Stop anytime. Guided mode uses your own count or an active timer; sensors estimate movement.</p>${btn('Choose a gentle stretch instead','gentle','','textbutton')}`}`,'ritual');$('#modal').innerHTML=''}
function timerCue(id,amount){if(id==='dance')return'Your move. Your rhythm. Keep it gentle.';if(id==='march')return'Small steps or seated heel lifts. Find your easy pace.';if(id==='breathe')return amount%10<4?'Breathe in gently · 4 seconds':'Breathe out slowly · 6 seconds';let third=current().target/3;return amount<third?'Slowly roll your shoulders and breathe.':amount<third*2?'Reach gently upward, seated or standing.':'Relax your arms. Welcome the day.'}
function playRitual(){if(S.soundEnabled&&!muted)N?.play(session.alarm.tone,session.alarm.gentleSound,S.ritualVolume)}
function startRitual(){started=true;tickAt=performance.now();playRitual();N?.awake(true);render()}
function pauseRitual(){started=false;tickAt=0;N?.motion(false);N?.stopMusic();N?.awake(false);sensor=''}
function updateAmount(amount,mode){let s=current();if(mode)session.mode=mode;progress=Math.min(s.target,amount);reps=Math.floor(progress);session.amount=progress;if(progress>=s.target){session.finished=true;finished=true;pauseRitual();save();render()}else{save();render()}}
function newQuestion(){let d=current().difficulty,a=d>=3?2+Math.floor(Math.random()*11):d===2?10+Math.floor(Math.random()*21):1+Math.floor(Math.random()*9),b=d>=3?2+Math.floor(Math.random()*11):d===2?1+Math.floor(Math.random()*20):1+Math.floor(Math.random()*9),op=d>=3?'×':d===2&&Math.random()<.5?'−':'+';if(op==='−'&&b>a)[a,b]=[b,a];mathQ={a,b,op,answer:op==='×'?a*b:op==='−'?a-b:a+b}}
function newMemory(){memory={seq:[0,1,2,3].sort(()=>Math.random()-.5).slice(0,Math.min(4,current().difficulty+1)),cursor:0,show:true}}
function errorFeedback(t){feedback=t;let f=$('#feedback');if(f)f.textContent=t}
function completeStep(){let s=current(),m=mission(s.mission);session.completedSteps.push({mission:s.mission,amount:s.target,mode:session.mode||'guided'});if(session.stepIndex<session.steps.length-1){session.stepIndex++;session.amount=0;session.finished=false;session.mode='guided';resetStep();save();render();window.scrollTo(0,0);return}if(!session.practice&&!S.sunrises.some(x=>x.id===session.id)){let record={id:session.id,date:Date.now(),alarmID:session.alarm.id,steps:session.completedSteps,mood,durationSeconds:(Date.now()-session.startedAt)/1000};S.sunrises.push(record);if(session.alarm.wakeCheckMinutes)S.wakeChecks.push({id:C.uid(),alarmID:session.alarm.id,sunriseID:record.id,date:Date.now()+session.alarm.wakeCheckMinutes*60000});}let old=session;session=null;if(!save()){session=old;session.completedSteps.pop();return}pauseRitual();screen='';render();window.scrollTo(0,0)}
let checkID='',checkTaps=0;
function renderCheck(){page(`<div class="eyebrow">YOUR WAKE-UP CHECK</div><h1>Still awake, sunshine?</h1><img class="mascot" src="art/sun.png" alt=""><p>Three little sun taps. Then confirm you are awake.</p><div class="progressnumber">${checkTaps} / 3</div>${checkTaps<3?btn('Tap the sun','checkTap','sun'):btn("I'm awake · confirm",'confirmAwake','check')}${btn('Cancel check','dismissCheck','','textbutton')}`,'ritual');$('#modal').innerHTML=''}
function alarmArrived(id){N?.stopAlarm();S.welcomed=true;if(id.startsWith('check:')){checkID=id.slice(6);checkTaps=0;screen='check';session=null;render();return}let a=S.alarms.find(a=>a.id===id);if(!a){toast('This alarm is no longer saved.');return}if(a.scheduleMode==='dated'||a.scheduleMode==='weekly'&&!a.weekdays.length)a.enabled=false;if(a.nextOverride&&a.nextOverride<=Date.now()+60000)a.nextOverride=null;startSession(a,false)}
let dim=false;
function bedside(){page(`<div class="row between">${btn('Close','bedsideClose','','textbutton')}${btn(dim?'Brighter':'Dim','dim','','textbutton')}</div><div class="stack center"><div class="clock" id="clock">${fmt(Date.now())}</div><div>${fmt(Date.now(),{weekday:'long',month:'long',day:'numeric'})}</div><p class="small">${(()=>{let a=S.alarms.filter(a=>C.nextFire(a)).sort((a,b)=>C.nextFire(a)-C.nextFire(b))[0];return a?esc(a.label)+' · '+dateTime(C.nextFire(a)):'No enabled alarm'})()}</p></div><p class="small center">System alarms keep working when this view is closed.</p>`,'bedside'+(dim?' dim':''));$('#modal').innerHTML='';N?.awake(true)}
function newAlarm(id){if(!id&&S.alarms.filter(a=>!a.isNap).length>=(B.active?20:2)){openScreen('plus');return}draft=id?structuredClone(S.alarms.find(a=>a.id===id)):C.alarm();openScreen('editor')}
function quickNap(minutes){let a=C.alarm();a.isNap=true;a.label='A little rest';a.route=[C.step('sunTaps')];a.scheduleMode='dated';a.datedAt=Date.now()+minutes*60000;let d=new Date(a.datedAt);a.hour=d.getHours();a.minute=d.getMinutes();S.alarms=S.alarms.filter(a=>!a.isNap);S.alarms.push(a);if(save()){toast('Nap alarm set for '+fmt(a.datedAt));N?.ensureNotifications();render()}}
function exportJournal(){const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';let csv='Date,Alarm ID,Steps,Completion modes,Mood,Duration seconds,Awake confirmed at\r\n'+S.sunrises.map(r=>[new Date(r.date).toISOString(),r.alarmID,r.steps.map(s=>`${mission(s.mission).title}: ${s.amount}`).join(' → '),r.steps.map(s=>s.mode).join(' → '),r.mood,r.durationSeconds,r.wakeCheckConfirmedAt?new Date(r.wakeCheckConfirmedAt).toISOString():''].map(q).join(',')).join('\r\n');N?.export(csv)}
function appBack(){if(session){if(confirm('Exit without saving a sunrise? Your completed route steps will not be credited.')){pauseRitual();session=null;save();render()}return}if(screen==='step'){screen='editor';render();return}if(screen==='destinations'&&returnScreen){screen=returnScreen;returnScreen='';render();return}if(screen==='bedside'){N?.awake(false);screen='tools';render();return}if(screen==='readiness'){screen='tools';render();return}if(screen==='check'){screen='';render();return}screen='';$('#modal').innerHTML='';render()}
async function action(value){let [a,...parts]=value.split(':'),id=parts.join(':');
 if(a==='welcome'){S.welcomed=true;save();render()}
 else if(a==='tab'){pauseRitual();tab=id;screen='';render();window.scrollTo(0,0)}
 else if(a==='new'||a==='edit')newAlarm(id);
 else if(a==='screen')openScreen(id);
 else if(a==='back'||a==='close')appBack();
 else if(a==='weekday'){let d=+id;draft.weekdays=draft.weekdays.includes(d)?draft.weekdays.filter(x=>x!==d):[...draft.weekdays,d];editor()}
 else if(a==='step'){editingStep=+id;screen='step';renderScreen()}
 else if(a==='addStep'){draft.route.push(C.step('daylight'));editor()}
 else if(a==='earlier'||a==='later'){let i=+id,j=i+(a==='earlier'?-1:1);[draft.route[i],draft.route[j]]=[draft.route[j],draft.route[i]];editor()}
 else if(a==='removeStep'){draft.route.splice(+id,1);editor()}
 else if(a==='savePreset'){let name=prompt('Save route as','My morning route');if(name?.trim()){S.presets.push({id:C.uid(),name:name.trim().slice(0,48),steps:structuredClone(draft.route)});save();toast('Reusable route saved.')}}
 else if(a==='saveAlarm'){draft.label=draft.label.trim().slice(0,48)||'My morning';if(!C.nextFire({...draft,enabled:true})){toast('Choose a future date.');return}if(!B.active)draft.route=draft.route.map(s=>({...s,target:mission(s.mission).target}));let old=structuredClone(S.alarms),index=S.alarms.findIndex(a=>a.id===draft.id);if(index>=0)S.alarms[index]=draft;else S.alarms.push(draft);if(save()){screen='';render();N?.ensureNotifications()}else S.alarms=old;}
 else if(a==='deleteAlarm'){if(confirm('Remove this alarm?')){S.alarms=S.alarms.filter(a=>a.id!==draft.id);save();screen='';render()}}
 else if(a==='skip'){let alarm=S.alarms.find(x=>x.id===id),next=C.nextFire(alarm);if(next){if(alarm.nextOverride===next)alarm.nextOverride=null;alarm.skippedDates.push(C.localDate(next));if(alarm.scheduleMode==='dated'||alarm.scheduleMode==='weekly'&&!alarm.weekdays.length)alarm.enabled=false;save();render()}}
 else if(a==='addDayOff'){let d=$('#skipDate').value;if(d&&!draft.skippedDates.includes(d))draft.skippedDates.push(d);editor()}
 else if(a==='removeDay'){draft.skippedDates=draft.skippedDates.filter(d=>d!==id);editor()}
 else if(a==='endPause'){draft.pausedUntil=null;editor()}
 else if(a==='preview')N?.play(draft.tone,draft.gentleSound,S.ritualVolume);
 else if(a==='stopPreview')N?.stopMusic();
 else if(a==='importAudio')N?.importAudio();
 else if(a==='permissions')N?.permissions();
 else if(a==='fullScreenPermission')N?.fullScreenPermission();
 else if(a==='refresh'){save();toast('Calendar plans refreshed.');readiness()}
 else if(a==='practice'){let alarm=C.alarm();alarm.route=[C.step(id)];startSession(alarm,true)}
 else if(a==='practiceRoute'){let alarm=C.alarm();alarm.route=['sunTaps','stretch','daylight'].map(C.step);startSession(alarm,true)}
 else if(a==='longDance'){let alarm=C.alarm();alarm.route=[{...C.step('dance'),target:60}];startSession(alarm,true)}
 else if(a==='presetPractice'){let alarm=C.alarm();alarm.route=structuredClone(S.presets.find(p=>p.id===id).steps);if(!B.active)alarm.route.forEach(s=>s.target=mission(s.mission).target);startSession(alarm,true)}
 else if(a==='start')startRitual();
 else if(a==='pause'){pauseRitual();save();render()}
 else if(a==='rep')updateAmount(reps+1,'self-reported repetitions');
 else if(a==='sunTap'){if(+id===[0,3,1,2][reps%4])updateAmount(reps+1,'sun taps')}
 else if(a==='answerMath'){let answer=$('#answer').value.trim();if(answer!==''&&Number(answer)===mathQ.answer){mathQ=null;feedback='';updateAmount(reps+1,'typed maths')}else errorFeedback('Try again. There is no rush.')}
 else if(a==='memoryToggle'){memory.show=!memory.show;memory.cursor=0;feedback='';render()}
 else if(a==='memoryTap'){if(memory.show)return;if(memory.seq[memory.cursor]===+id){memory.cursor++;if(memory.cursor===memory.seq.length){memory=null;feedback='';updateAmount(reps+1,'memory trail')}}else{memory.cursor=0;errorFeedback('Start this trail again, or replay it.')}}
 else if(a==='answerWords'){if(C.normalize($('#answer').value)===C.normalize(current().intention)){updateAmount(current().target,'typed intention')}else errorFeedback('Try matching your intention. Punctuation and letter case do not need to match.')}
 else if(a==='selfAction'||a==='destinationManual')updateAmount(current().target,'self-reported action');
 else if(a==='scanRitual'){scanSave=false;N?.camera('scan')}
 else if(a==='cameraPose'){session.mode='camera estimate';N?.camera('pose:'+Math.max(1,current().target-reps))}
 else if(a==='motion'){N?.motion(true)}
 else if(a==='guided'){sensor='';N?.motion(false);session.mode='guided';render()}
 else if(a==='mute'){muted=!muted;if(muted)N?.stopMusic();else if(started)playRitual();render()}
 else if(a==='gentle'){pauseRitual();session.steps[session.stepIndex]=C.step('stretch');session.amount=0;session.finished=false;resetStep();save();render()}
 else if(a==='completeStep')completeStep();
 else if(a==='exit')appBack();
 else if(a==='mood'){mood=id;render()}
 else if(a==='setNap')quickNap(nap);
 else if(a==='testAlarm')quickNap(1);
 else if(a==='pauseAll'){let t=Date.parse($('#pauseUntil').value);if(!(t>Date.now())){toast('Choose a future pause time.');return}S.alarms.filter(a=>a.enabled).forEach(a=>a.pausedUntil=t);if(save())toast('Pause saved. Your next wake-ups appear on Morning.')}
 else if(a==='cancelcheck'){S.wakeChecks=S.wakeChecks.filter(c=>c.id!==id);save();render()}
 else if(a==='checkTap'){checkTaps++;render()}
 else if(a==='confirmAwake'){if(checkTaps<3)return;let check=S.wakeChecks.find(c=>c.id===checkID),r=S.sunrises.find(r=>r.id===check?.sunriseID);if(r)r.wakeCheckConfirmedAt=Date.now();S.wakeChecks=S.wakeChecks.filter(c=>c.id!==checkID);save();screen='';render()}
 else if(a==='dismissCheck'){S.wakeChecks=S.wakeChecks.filter(c=>c.id!==checkID);save();screen='';render()}
 else if(a==='bedside'){screen='bedside';render()}
 else if(a==='dim'){dim=!dim;bedside()}
 else if(a==='bedsideClose'){N?.awake(false);screen='tools';render()}
 else if(a==='export')exportJournal();
 else if(a==='clearJournal'){if(confirm('Clear all sunrise entries on this device? Your alarms and subscription remain active.')){S.sunrises=[];S.wakeChecks=[];save();render()}}
 else if(a==='reviewAccess')N?.reviewAccess();
 else if(a==='restore')N?.restore();
 else if(a==='manage')N?.open('https://play.google.com/store/account/subscriptions?package=com.oanarinaldi.wakemeup');
 else if(a==='plan'){selectedPlan=id;plus()}
 else if(a==='subscribe'){if(!B.busy)N?.buy(B.plans.find(x=>x.id===selectedPlan)?.id||B.plans[0]?.id||'')}
 else if(a==='link')N?.open('https://oanarinaldi.com/wakemeup'+id+'.html');
 else if(a==='contact')N?.open('mailto:oanaunciuleanu@gmail.com?subject=Wake%20Me%20Up%20Support');
 else if(a==='stepDestinations'){returnScreen='step';openScreen('destinations')}
 else if(a==='scanDestination'){scanSave=true;globalThis.destinationName=$('#destinationName').value.trim()||'My destination';N?.camera('scan')}
 else if(a==='removeDestination'){S.destinations=S.destinations.filter(d=>d.id!==id);for(let a of S.alarms)for(let s of a.route)if(s.destinationID===id)s.destinationID=null;if(draft)for(let s of draft.route)if(s.destinationID===id)s.destinationID=null;save();destinations()}
 else if(a==='removePreset'){S.presets=S.presets.filter(p=>p.id!==id);save();library()}
 else if(a==='removeTone'){if(S.alarms.some(a=>a.tone===id)){toast('Change alarms using this sound before removing it.');return}S.importedTones=S.importedTones.filter(t=>t.id!==id);if(save())N?.removeAudio(id);library()}
}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(el&&!el.disabled)action(el.dataset.action)});
document.addEventListener('change',e=>{let el=e.target;
 if(el.dataset.pref){let k=el.dataset.pref;if(k==='bedtime'){[S.bedtimeHour,S.bedtimeMinute]=el.value.split(':').map(Number)}else S[k]=el.type==='checkbox'?el.checked:el.type==='range'||el.type==='number'?Number(el.value):el.value;save();if(el.type==='checkbox'&&k==='bedtimeEnabled'&&el.checked)N?.ensureNotifications();return}
 if(el.dataset.alarm){let a=S.alarms.find(a=>a.id===el.dataset.alarm);a.enabled=el.checked;if(!save())a.enabled=!el.checked;render();return}
 if(el.dataset.draft){let k=el.dataset.draft,v=el.type==='checkbox'?el.checked:el.value;if(k==='time'){[draft.hour,draft.minute]=v.split(':').map(Number)}else if(['datedAt','cycleStart','nextOverride'].includes(k)){draft[k]=new Date(v).getTime();if(k==='datedAt'){let d=new Date(draft[k]);draft.hour=d.getHours();draft.minute=d.getMinutes()}}else if(k==='preset'){let steps=v==='gentle'?['breathe','stretch','daylight']:v==='focus'?['math','march','scanCode']:v==='joy'?['sunTaps','dance','water']:null;if(steps)draft.route=steps.map(C.step);else if(v)draft.route=structuredClone(S.presets.find(p=>p.id===v).steps)}else if(k==='override')draft.nextOverride=v?C.nextFire({...draft,enabled:true}):null;else draft[k]=['workDays','restDays','snoozeMinutes','wakeCheckMinutes'].includes(k)?Math.max(k==='workDays'||k==='restDays'?1:0,Math.min(30,Number(v))):v;if(k!=='label')editor();return}
 if(el.dataset.step){let k=el.dataset.step,s=draft.route[editingStep];if(k==='mission')draft.route[editingStep]=C.step(el.value);else s[k]=['target','difficulty'].includes(k)?Math.max(1,Math.min(k==='difficulty'?3:mission(s.mission).unit==='seconds'?180:['math','memory'].includes(s.mission)?10:30,Number(el.value))):el.value||null;if(k!=='intention')stepEditor();return}
 if(el.dataset.tool){nap=+el.value;tools()}
});
function nativeEvent(type,data){if(type==='billing'){B=data;if(screen==='plus')plus()}else if(type==='reviewAccess'){B=data;render()}else if(type==='alarm')alarmArrived(data);else if(type==='pause'){if(session){pauseRitual();save();render()}}else if(type==='resume'){if(screen==='readiness')readiness()}else if(type==='movement')movingAt=performance.now();else if(type==='motionReady'){sensor='motion';session.mode='motion estimate';startRitual()}else if(type==='sensorError'){toast(data)}else if(type==='audioImported'){S.importedTones.push(data);if(draft)draft.tone=data.id;save();if(screen==='editor')editor()}else if(type==='cameraResult'){if(data.startsWith('pose:')&&session){updateAmount(reps+Number(data.slice(5)),'camera estimate')}else if(scanSave){let digest=N.hash(data);S.destinations.push({id:C.uid(),name:globalThis.destinationName,digest});save();destinations();toast('Destination saved.')}else if(session){let d=S.destinations.find(d=>d.id===current().destinationID);if(d&&N.hash(data)===d.digest)updateAmount(current().target,'matching code scan');else{errorFeedback('That code does not match your saved destination.');render()}}}}
setInterval(()=>{let now=performance.now();if(screen==='bedside'&&$('#clock'))$('#clock').textContent=fmt(Date.now());if(!session||!started||session.finished||mission(current().mission).unit!=='seconds'){tickAt=now;return}let delta=Math.min(.2,(now-tickAt)/1000);tickAt=now;if(document.hidden||sensor==='motion'&&now-movingAt>800)return;let before=Math.floor(progress);progress=Math.min(current().target,progress+delta);if(Math.floor(progress)!==before){session.amount=progress;save();let n=$('#progressNumber'),b=$('#progressBar'),cue=$('#cue');if(n)n.textContent=Math.floor(progress)+' / '+current().target;if(b)b.style.width=progress/current().target*100+'%';if(cue)cue.textContent=timerCue(current().mission,Math.floor(progress));let sun=$('#risingSun');if(sun)sun.style.transform=`translateY(${(1-progress/current().target)*28}px)`}if(progress>=current().target){session.finished=true;pauseRitual();save();render()}},100);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&session){pauseRitual();save();render()}});
if(session){resetStep()}render();if(initial.alarm)alarmArrived(initial.alarm);else if(initial.shortcut==='practice'){S.welcomed=true;tab='Move';render()}else if(initial.shortcut==='nap'){S.welcomed=true;screen='tools';render()}
